SPARQL
SELECT ?g (COUNT(*) AS ?t) WHERE { GRAPH ?g { ?s ?p ?o }
  FILTER (CONTAINS(STR(?g), 'agent-rdf-memory')) }
GROUP BY ?g ORDER BY DESC(?t);